<?php $crud=['table'=>'sales','title'=>'Sales / Invoices','singular'=>'Sale','permission'=>'sales.view','readonly'=>true,'search'=>['invoice_no','status','customer','phone'],'list_sql'=>function($qterm=null){ $where='WHERE s.branch_id=?'; if(trim((string)$qterm)!=='') $where.=' AND (s.invoice_no LIKE ? OR s.status LIKE ? OR c.full_name LIKE ? OR c.phone LIKE ?)'; return 'SELECT s.*,c.full_name customer,c.phone phone FROM sales s LEFT JOIN customers c ON c.id=s.customer_id '.$where.' ORDER BY s.id DESC LIMIT 500'; },'list_params'=>function($qterm=null){ $params=[current_branch_id()]; if(trim((string)$qterm)!==''){ $like='%'.trim((string)$qterm).'%'; array_push($params,$like,$like,$like,$like); } return $params; },'fields'=>[],'list'=>['sale_date'=>'Date','invoice_no'=>'Invoice','customer'=>'Customer','total_amount'=>'Total','paid_amount'=>'Paid','balance_amount'=>'Balance','status'=>'Status'],'row_actions'=>fn($r)=>'<a class="btn small secondary" href="sale_view.php?id='.(int)$r['id'].'">Open</a> <a class="btn small light" target="_blank" href="receipt.php?id='.(int)$r['id'].'">Receipt</a>']; require dirname(__DIR__).'/includes/crud.php';